//! Journal lines, as `journalctl --output=json` writes them, for the tests.
//!
//! WRITTEN BY HAND in the shape the journal has: every field a string (the
//! timestamps too), `__CURSOR` and `__REALTIME_TIMESTAMP` on every line, the
//! kernel's lines with `_TRANSPORT=kernel` and `SYSLOG_IDENTIFIER=kernel`,
//! systemd's words about a unit from the person's manager (`USER_UNIT`, sent
//! by `user@1000.service`) or the system's (`UNIT`, sent by `init.scope`), and
//! oomd's under its own identifier. The messages are the kernel's and systemd's
//! own formats (`mm/oom_kill.c`, `src/oom/oomd-manager.c`, `src/core/unit.c`).
//! Rust constants and not files: the Nix build of the crate sees only `.rs`.

/// The second the kill happened, as the journal's clock wrote it.
pub const AT: i64 = 1_790_000_000;

